const useIsCompact = () => {
  const [compact, setCompact] = React.useState(() =>
    typeof window !== 'undefined' ? window.matchMedia('(max-width: 639px)').matches : true
  );
  React.useEffect(() => {
    const mq = window.matchMedia('(max-width: 639px)');
    const onChange = () => setCompact(mq.matches);
    onChange();
    mq.addEventListener('change', onChange);
    return () => mq.removeEventListener('change', onChange);
  }, []);
  return compact;
};

const staffFetch = async (path, options = {}) => {
  const res = await fetch(`${API_BASE}/api/v1/calendar/website-bookings${path}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      'X-Staff-Review-Key': STAFF_KEY,
      ...(options.headers || {}),
    },
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) {
    throw new Error(data.message || data.error || 'Request failed');
  }
  return data;
};

const formatTime = (minutes) => {
  const h = Math.floor(Number(minutes) / 60);
  const m = Number(minutes) % 60;
  const period = h >= 12 ? 'PM' : 'AM';
  const hour12 = h % 12 || 12;
  return m === 0 ? `${hour12}:00 ${period}` : `${hour12}:${String(m).padStart(2, '0')} ${period}`;
};

const formatMoney = (value) =>
  `₱${Number(value || 0).toLocaleString('en-PH', { maximumFractionDigits: 0 })}`;

const formatSubmittedAt = (iso) => {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return '—';
  return d.toLocaleString('en-PH', {
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });
};

