const formatDateHeading = (dateStr) => {
  const d = new Date(`${dateStr}T12:00:00`);
  if (Number.isNaN(d.getTime())) return dateStr;
  return d.toLocaleDateString('en-PH', {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
  });
};

const asNumber = (value, fallback = 0) => {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
};

const slotHours = (slot) =>
  Math.max(0, (asNumber(slot?.endTime) - asNumber(slot?.startTime)) / 60);

/** Build court + add-on line items from booking payload for staff review. */
const buildOrderBreakdown = (booking, settings = {}) => {
  const slots = booking?.slots || [];
  const details =
    booking?.renter_details && typeof booking.renter_details === 'object'
      ? booking.renter_details
      : {};

  const courtLines = slots.map((s) => ({
    key: `${s.date}-${s.courtId}-${s.startTime}`,
    date: s.date,
    label: `C${s.courtId} · ${formatTime(s.startTime)}–${formatTime(s.endTime)}`,
    amount: asNumber(s.price, 0),
    hours: slotHours(s),
  }));
  const courtTotal = courtLines.reduce((sum, line) => sum + line.amount, 0);
  const totalCourtHours = courtLines.reduce((sum, line) => sum + line.hours, 0);

  const pickleCamOn = !!details.pickleCam;
  const pickleCamMode = details.pickleCamPricingMode === 'flat' ? 'flat' : 'hourly';
  const pickleCamRate = asNumber(
    details.pickleCamFee,
    asNumber(settings.pickleCamFee, DEFAULT_PICKLECAM_FEE)
  );
  const pickleCamCourts = Math.min(
    5,
    Math.max(1, Math.floor(asNumber(details.pickleCamCourtCount, 1)))
  );
  const pickleCamHours =
    asNumber(details.pickleCamHours, 0) > 0
      ? asNumber(details.pickleCamHours, 0)
      : totalCourtHours || 1;
  const pickleCamAmount = !pickleCamOn
    ? 0
    : pickleCamMode === 'hourly'
      ? Math.round(pickleCamRate * pickleCamHours * pickleCamCourts)
      : pickleCamRate;

  const ballQty = Math.max(0, Math.floor(asNumber(details.ballQty, 0)));
  const ballUnit = asNumber(details.ballFee, asNumber(settings.ballFee, DEFAULT_BALL_FEE));
  const ballsAmount = ballQty > 0 ? ballQty * ballUnit : 0;

  const discountPct = asNumber(details.discount, 0);
  const gross = courtTotal + pickleCamAmount + ballsAmount;
  const discountAmount =
    discountPct > 0
      ? Math.round(gross * (discountPct / 100))
      : Math.max(0, asNumber(details.discountAmount, 0));
  const computedNet = Math.max(0, gross - discountAmount);
  const storedTotal = asNumber(booking?.total_price, computedNet);

  return {
    courtLines,
    courtTotal,
    totalCourtHours,
    pickleCam: pickleCamOn
      ? {
          mode: pickleCamMode,
          rate: pickleCamRate,
          hours: pickleCamHours,
          courts: pickleCamCourts,
          amount: pickleCamAmount,
          formula:
            pickleCamMode === 'hourly'
              ? `${pickleCamHours}h × ${pickleCamCourts} cam court${pickleCamCourts !== 1 ? 's' : ''} × ${formatMoney(pickleCamRate)}/hr`
              : `Flat fee ${formatMoney(pickleCamRate)}`,
        }
      : null,
    balls:
      ballQty > 0
        ? {
            qty: ballQty,
            unit: ballUnit,
            amount: ballsAmount,
            formula: `${ballQty} × ${formatMoney(ballUnit)}`,
          }
        : null,
    discount:
      discountAmount > 0
        ? {
            pct: discountPct,
            amount: discountAmount,
            label: discountPct > 0 ? `Discount (${discountPct}%)` : 'Discount',
          }
        : null,
    gross,
    computedNet,
    total: storedTotal,
    hasAddons: pickleCamOn || ballQty > 0 || discountAmount > 0,
  };
};

/** Group slots → [{ date, rows: [{ startTime, endTime, courts, priceSum }] }] */
const groupSlots = (slots = []) => {
  const byDate = new Map();
  for (const s of slots) {
    if (!byDate.has(s.date)) byDate.set(s.date, new Map());
    const byTime = byDate.get(s.date);
    const key = `${s.startTime}-${s.endTime ?? ''}`;
    if (!byTime.has(key)) {
      byTime.set(key, {
        startTime: s.startTime,
        endTime: s.endTime,
        courts: [],
        priceSum: 0,
      });
    }
    const row = byTime.get(key);
    row.courts.push(s.courtId);
    row.priceSum += asNumber(s.price, 0);
  }
  return [...byDate.entries()].map(([date, byTime]) => ({
    date,
    rows: [...byTime.values()].map((row) => ({
      ...row,
      courts: [...row.courts].sort((a, b) => a - b),
    })),
  }));
};

const groupCourtLinesByDate = (lines) => {
  const map = new Map();
  for (const line of lines) {
    const date = line.date || '';
    if (!map.has(date)) map.set(date, []);
    map.get(date).push(line);
  }
  return [...map.entries()];
};

function SlotSchedule({ slots }) {
  const groups = groupSlots(slots);
  const [expanded, setExpanded] = React.useState(false);

  if (!groups.length) {
    return <p className="text-xs text-slate-400">No courts booked</p>;
  }

  const totalHours = slots.reduce((sum, s) => sum + slotHours(s), 0);
  const courtCount = new Set(slots.map((s) => s.courtId)).size;
  const hoursLabel = Number.isInteger(totalHours) ? String(totalHours) : totalHours.toFixed(1);
  const totalRows = groups.reduce((n, g) => n + g.rows.length, 0);
  const COLLAPSE_AFTER = 3;
  const needsCollapse = totalRows > COLLAPSE_AFTER;

  let shown = 0;
  const visibleGroups = groups
    .map((g) => {
      if (expanded || !needsCollapse) return g;
      const remaining = COLLAPSE_AFTER - shown;
      if (remaining <= 0) return null;
      const rows = g.rows.slice(0, remaining);
      shown += rows.length;
      return { ...g, rows };
    })
    .filter(Boolean);

  return (
    <div className="rounded-lg bg-slate-50 border border-slate-100 overflow-hidden">
      <div className="flex items-center justify-between gap-2 px-3 py-2 border-b border-slate-100">
        <span className="text-[11px] font-semibold uppercase tracking-wide text-slate-500">
          Schedule
        </span>
        <span className="text-[11px] text-slate-500 tabular-nums text-right leading-snug">
          {hoursLabel}h · {courtCount} court{courtCount === 1 ? '' : 's'} · {slots.length} slot
          {slots.length === 1 ? '' : 's'}
        </span>
      </div>
      <div className="divide-y divide-slate-100">
        {visibleGroups.map((g) => (
          <div key={g.date} className="px-3 py-2.5">
            <p className="text-xs font-semibold text-slate-800 mb-1.5">{formatDateHeading(g.date)}</p>
            <ul className="space-y-1.5">
              {g.rows.map((row) => (
                <li
                  key={`${row.startTime}-${row.endTime}`}
                  className="flex items-start sm:items-center gap-2 min-w-0"
                >
                  <span className="shrink-0 min-w-[4.75rem] text-xs tabular-nums text-slate-600 flex items-center gap-1 pt-0.5">
                    <Clock className="h-3 w-3 text-slate-400" />
                    {formatTime(row.startTime)}
                  </span>
                  <div className="flex flex-wrap gap-1 flex-1 min-w-0">
                    {row.courts.map((c) => (
                      <span
                        key={c}
                        className="inline-flex items-center justify-center min-w-[1.75rem] h-6 px-1.5 rounded-md bg-white border border-slate-200 text-[11px] font-semibold text-slate-700"
                      >
                        C{c}
                      </span>
                    ))}
                  </div>
                  {row.priceSum > 0 && (
                    <span className="shrink-0 text-[11px] font-semibold tabular-nums text-slate-700 pt-0.5">
                      {formatMoney(row.priceSum)}
                    </span>
                  )}
                </li>
              ))}
            </ul>
          </div>
        ))}
      </div>
      {needsCollapse && (
        <button
          type="button"
          onClick={() => setExpanded((v) => !v)}
          className="w-full min-h-10 px-3 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-100/80 border-t border-slate-100 touch-manipulation inline-flex items-center justify-center gap-1"
        >
          {expanded ? 'Show less' : `Show all ${totalRows} times`}
          <ChevronDown className={`h-3.5 w-3.5 transition-transform ${expanded ? 'rotate-180' : ''}`} />
        </button>
      )}
    </div>
  );
}

